-- Comparative diagnostic, using the exact Git baseline generated by CI.
-- No Roblox engine latency, recipient fanout, or universal performance guarantee.
local currentPolicy, baselinePolicy, previousPolicy, currentGate, baselineGate, recentBaseline, defaultConfig, defaultData
if type(dofile)=="function" then
    currentPolicy=dofile("server/TextPolicy.lua")
    baselinePolicy=dofile("tests/.baseline/TextPolicy.lua")
    previousPolicy=dofile("tests/.baseline/PreviousPolicy.lua")
    defaultConfig=dofile("server/ChatConfiguration.lua")
    defaultData=dofile("server/ProfanityData.lua")
    currentGate=dofile("server/DeliveryGate.lua")
    baselineGate=dofile("tests/.baseline/DeliveryGate.lua")
    recentBaseline=dofile("tests/.baseline/RecentGate.lua")
else
    currentPolicy=require("../server/TextPolicy")
    baselinePolicy=require("./.baseline/TextPolicy")
    previousPolicy=require("./.baseline/PreviousPolicy")
    defaultConfig=require("../server/ChatConfiguration")
    defaultData=require("../server/ProfanityData")
    currentGate=require("../server/DeliveryGate")
    baselineGate=require("./.baseline/DeliveryGate")
    recentBaseline=require("./.baseline/RecentGate")
end

local function timing(run)
    local before=os.clock()
    local digest=run()
    return os.clock()-before,digest
end
local function compare(name, baseline, current, n, trials)
    trials=trials or 3
    local bTimes,cTimes={},{}
    local digest
    for trial=1,trials do
        local bt,bd,ct,cd
        if trial%2==1 then
            bt,bd=timing(baseline)
            ct,cd=timing(current)
        else
            ct,cd=timing(current)
            bt,bd=timing(baseline)
        end
        assert(bd==cd and (digest==nil or digest==bd),"benchmark semantic mismatch: "..name)
        digest=bd
        bTimes[#bTimes+1]=bt
        cTimes[#cTimes+1]=ct
    end
    table.sort(bTimes)
    table.sort(cTimes)
    local median=math.floor(trials/2)+1
    print(string.format("BENCH %s n=%d trials=%d baseline_ms=%.3f current_ms=%.3f ratio=%.3f checksum=%d",name,n,trials,bTimes[median]*1000,cTimes[median]*1000,bTimes[median]/math.max(cTimes[median],1e-9),digest))
end

local function syntheticWord(i, len)
    local chars={}
    for k=1,len do
        chars[k]=string.char(97+(i%26))
        i=math.floor(i/26)
    end
    return table.concat(chars)
end
local function policyRunner(policy, data, config, corpus, repetitions)
    local check=policy.new(config,data)
    return function()
        local digest=0
        for i=1,repetitions do
            for j,msg in ipairs(corpus) do
                local ok=check(msg)
                digest=(digest*31+(ok and 1 or 0)+j)%2147483647
            end
        end
        return digest
    end
end
local config={MaxMessageBytes=512,MaxTokens=80,MaxTokenBytes=64,EnableFuzzy=true}
local words,phrases={},{}
for i=1,256 do
    words[i]=syntheticWord(i,20)
    phrases[i]=syntheticWord(i,8).." "..syntheticWord(i+300,8)
end
local data={Words=words,Phrases=phrases,AllowWords={},BlockSymbols={}}
local corpus={
    string.rep("zbcdefghijklmnopqrst ",18),
    string.rep("qwertyuiopasdfghjklz ",18),
    words[11],
    "hello "..phrases[20].." there",
    words[5]:sub(1,19).."z",
    "hello team",
    "áéíóú vamos jogar",
    string.rep("hello ",40),
}
-- Baseline and current fuzzy semantics are equal for this ASCII dictionary (all length 20).
compare("lexical_256_rules_fuzzy",policyRunner(baselinePolicy,data,config,corpus,20),policyRunner(currentPolicy,data,config,corpus,20),#corpus*20)
config.EnableFuzzy=false
compare("lexical_256_rules_exact",policyRunner(baselinePolicy,data,config,corpus,100),policyRunner(currentPolicy,data,config,corpus,100),#corpus*100)

local typical={"hello team","vamos al tablero","bom dia","good game!","this is a test","12345","nice class","cereza","attack the boss","hola, ¿cómo estás?","obrigado!","日本語"}
compare("lexical_typical_vs_pre_ascii",policyRunner(previousPolicy,defaultData,defaultConfig,typical,1000),policyRunner(currentPolicy,defaultData,defaultConfig,typical,1000),#typical*1000)
local gateConfig={MessagesPerSecond=20,DecisionTTL=10,MaxCachedMessages=256}
local function oldAllow() return true,"allow" end
local function gateRunner(old, mode, n, implementation)
    return function()
        local gate=(implementation or (old and baselineGate or currentGate)).new(gateConfig)
        local digest=0
        for i=1,n do
            local id,now
            if mode=="fanout" then
                local message=math.floor((i-1)/50)
                id=tostring(message)
                now=message*0.06
            elseif mode=="saturated" then
                id=tostring(i)
                now=i*0.005
            else
                id=tostring(i)
                now=i*0.06
            end
            local ok
            if old then ok=gate:Decide("sender",id,now,oldAllow)
            else ok=gate:Admit("sender",id,now,"channel") end
            digest=(digest*31+(ok and 1 or 0))%2147483647
        end
        return digest
    end
end
for _, mode in ipairs({"unique","saturated","fanout"}) do
    compare("admission_"..mode,gateRunner(true,mode,30000),gateRunner(false,mode,30000),30000)
end
-- Longer workloads isolate lookup cost from string generation, using identical
-- pre-built inputs and five alternating measurements. The mixed case has
-- independent sender objects and two channel objects.
local function buildWorkload(mode,n)
    local ids,times,owners,channels={},{},{},{}
    local senderList,channelList={{},{},{},{}},{{},{}}
    for i=1,n do
        local j=mode=="fanout" and math.floor((i-1)/50) or i
        local mixed=mode=="mixed"
        ids[i]=tostring(j)
        times[i]=j*(mode=="saturated" and 0.005 or 0.06)
        owners[i]=senderList[mixed and (i%4+1) or 1]
        channels[i]=channelList[mixed and (math.floor(i/4)%2+1) or 1]
    end
    return {ids,times,owners,channels}
end
local function prebuiltRunner(implementation,work,n)
    return function()
        local gate=implementation.new(gateConfig)
        local digest=0
        for i=1,n do
            local ok=gate:Admit(work[3][i],work[1][i],work[2][i],work[4][i])
            digest=(digest*31+(ok and 1 or 0))%2147483647
        end
        return digest
    end
end
for _,mode in ipairs({"unique","saturated","fanout","mixed"}) do
    local n=300000
    local work=buildWorkload(mode,n)
    compare("current_vs_lite_"..mode,prebuiltRunner(recentBaseline,work,n),prebuiltRunner(currentGate,work,n),n,5)
end
